use std::{fs,path::Path};use serde_json::{json,Value};use sha2::{Digest,Sha256};
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/g2-queue-scan-count175");let method=fs::read_to_string(r.join("lifo-method.rs")).unwrap();fs::write(r.join("lifo-impl.rs"),format!("impl Model {{\n{method}\n}}\n")).unwrap();fs::copy(r.join("pins.json"),r.join("pins-initial.json")).unwrap();fs::copy(r.join("plan.json"),r.join("plan-initial.json")).unwrap();let mut pins:Value=serde_json::from_slice(&fs::read(r.join("pins.json")).unwrap()).unwrap();for p in["model.rs","model-initial.rs","lifo-impl.rs","repair.rs","repair"]{let p=r.join(p);pins[p.display().to_string()]=json!(hash(&p));}fs::write(r.join("pins-fixed.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();let mut plan:Value=serde_json::from_slice(&fs::read(r.join("plan.json")).unwrap()).unwrap();plan["source_pins"]=json!(r.join("pins-fixed.json"));fs::write(r.join("plan-fixed.json"),serde_json::to_vec_pretty(&plan).unwrap()).unwrap();fs::rename(r.join("runs"),r.join("runs-initial-include-failure")).unwrap();}
